res_open = primitives.call(
    name="submit_capx_action", action="open_gripper", native_api=True, parameters={}
)
res_goto = primitives.call(
    name="submit_capx_action",
    action="goto_pose",
    native_api=True,
    parameters={
        "position": [0.2475, 0.198, 0.032],
        "quaternion_wxyz": [0.0, 1.0, 0.0, 0.0],
        "z_approach": 0.10,
    },
)
res_close = primitives.call(
    name="submit_capx_action", action="close_gripper", native_api=True, parameters={}
)
res_obs = primitives.call(name="observe_capx_scene")
if res_obs.ok:
    pub = res_obs.output.get("public_observation", {})
    print("cartesian_pos after grasp:", pub.get("robot_cartesian_pos"))

res_get_obs = primitives.call(
    name="submit_capx_action", action="get_observation", native_api=True, parameters={}
)
if res_get_obs.ok:
    nar_obs = res_get_obs.output["native_api_result"]
    print("curr cartesian_pos:", nar_obs["robot_cartesian_pos"]["values"])
    print("curr joint_pos:", nar_obs["robot_joint_pos"]["values"])

